from typing import List, Optional
from datetime import datetime
from pydantic import BaseModel
from app.schemas.extraction import (
    PartyResponse,
    ClauseResponse,
    ObligationResponse,
    UnclearTermResponse,
)
from app.schemas.reminder import CalculatedReminderResponse

LEGAL_DISCLAIMER_TEXT = (
    "DISCLAIMER: This document is an information-management summary generated by an automated "
    "information-management system. It is provided solely for administrative and organizational tracking "
    "purposes. It does not constitute legal advice, a formal legal opinion, or a recommendation. "
    "Users should consult qualified legal counsel for any legal interpretation or decision-making."
)

class ReviewedContractSummaryResponse(BaseModel):
    contract_id: int
    contract_title: str
    version_number: int
    version_id: int
    effective_date: Optional[str] = None
    expiry_date: Optional[str] = None
    renewal_summary: Optional[str] = None
    termination_summary: Optional[str] = None
    approved_parties: List[PartyResponse] = []
    approved_clauses: List[ClauseResponse] = []
    approved_obligations: List[ObligationResponse] = []
    calculated_reminders: List[CalculatedReminderResponse] = []
    flagged_unclear_terms: List[UnclearTermResponse] = []
    policy_checks_count: int = 0
    total_approved_items: int = 0
    total_pending_items: int = 0
    total_stale_items: int = 0
    disclaimer: str = LEGAL_DISCLAIMER_TEXT
    generated_at: datetime
    markdown_content: str
